import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Ayah } from './types';
import { RECITERS, TRANSLATIONS, RADIO_STREAM_URL } from './constants';
import { useQuran } from './hooks/useQuran';
import { useAudioController } from './hooks/useAudioController';
import { useTafsirModal } from './hooks/useTafsirModal';
import { usePrayerTimes } from './hooks/usePrayerTimes';
import { translations } from './translations';

import SurahSelector from './components/SurahSelector';
import ReciterSelector from './components/ReciterSelector';
import TranslationSelector from './components/TranslationSelector';
import AyahDisplay from './components/AyahDisplay';
import PlayerControls from './components/PlayerControls';
import TafsirModal from './components/TafsirModal';
import ErrorMessage from './components/ErrorMessage';
import PrayerTimes from './components/PrayerTimes';

const HeaderButton = React.forwardRef<HTMLButtonElement, {
  onClick: React.MouseEventHandler<HTMLButtonElement>;
  label: string;
  title: string;
  children: React.ReactNode;
  className?: string;
}>(({ onClick, label, title, children, className = '' }, ref) => (
  <div className="flex flex-col items-center justify-center w-14 text-center">
    <button ref={ref} onClick={onClick} title={title} aria-label={title} className={`h-10 w-10 flex items-center justify-center rounded-full transition-colors ${className}`}>
      {children}
    </button>
    <span className="text-xs text-gray-400 mt-1">{label}</span>
  </div>
));
HeaderButton.displayName = 'HeaderButton';


export function App() {
  const [language, setLanguage] = useState<'ar' | 'en'>(() => {
      const saved = localStorage.getItem('app_language');
      return (saved === 'en' || saved === 'ar') ? saved : 'ar';
  });

  const t = translations[language];

  const [selectedSurah, setSelectedSurah] = useState<number>(1);
  const [selectedReciter, setSelectedReciter] = useState<string>(RECITERS[0]?.identifier || '');
  const [selectedTranslation, setSelectedTranslation] = useState<string>(TRANSLATIONS[0]?.identifier || '');
  const [selectedAyah, setSelectedAyah] = useState<Ayah | null>(null);
  const [memorizationState, setMemorizationState] = useState<Record<number, number>>({});

  const handlePlaybackEnd = useCallback(() => {
    // Player no longer automatically hides after the 7th listen.
    // It stays open to allow for "Re-listen" and "Read" controls.
  }, []);

  const { surahs, surahData, isLoading, error, loadSurahData } = useQuran();
  const { isAyahPlaying, playAyah, isRadioPlaying, toggleRadio } = useAudioController(handlePlaybackEnd);
  const { isOpen: isTafsirOpen, tafsirAyah, tafsirContent, isTafsirLoading, showTafsir, closeTafsir } = useTafsirModal(t);
  const { location, setLocation, prayerTimes, isLoading: isPrayerTimesLoading, error: prayerTimesError } = usePrayerTimes();

  const [isSelectorPanelOpen, setIsSelectorPanelOpen] = useState(true);
  const [isPrayerTimesOpen, setIsPrayerTimesOpen] = useState(false);

  const [scrollToAyah, setScrollToAyah] = useState<{ surah: number; ayah: number } | null>(null);

  const ayahRefs = useRef<Record<number, HTMLLIElement | null>>({});
  const settingsPanelRef = useRef<HTMLDivElement>(null);
  const settingsButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
      document.documentElement.lang = language;
      document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
      localStorage.setItem('app_language', language);

      // Update font based on language
      if (language === 'en') {
          document.body.style.fontFamily = 'ui-sans-serif, system-ui, sans-serif';
      } else {
          document.body.style.fontFamily = "'Amiri', serif";
      }
  }, [language]);

  // This effect will create space for the player controls at the bottom of the page
  // so it doesn't overlap the footer.
  useEffect(() => {
    const playerHeight = '96px'; // Approximate height of the player controls
    if (selectedAyah) {
      document.body.style.paddingBottom = playerHeight;
    } else {
      document.body.style.paddingBottom = '0px';
    }
    // Cleanup on component unmount
    return () => {
      document.body.style.paddingBottom = '0px';
    };
  }, [selectedAyah]);

  useEffect(() => {
    if (surahs.length > 0) {
      if (scrollToAyah && selectedSurah === scrollToAyah.surah) {
        // Surah is already loaded or is loading, wait for it
      } else {
        loadSurahData(selectedSurah, selectedReciter, selectedTranslation);
      }
    }
  }, [selectedSurah, selectedReciter, selectedTranslation, surahs, loadSurahData]);

  useEffect(() => {
    if (surahData && scrollToAyah && surahData.number === scrollToAyah.surah) {
      const targetAyah = surahData.ayahs.find(a => a.numberInSurah === scrollToAyah.ayah);
      if (targetAyah) {
        setSelectedAyah(targetAyah);
      }
      setScrollToAyah(null); // Reset after scrolling
    }
  }, [surahData, scrollToAyah]);


  useEffect(() => {
    if (selectedAyah) {
      ayahRefs.current[selectedAyah.number]?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }
  }, [selectedAyah]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        settingsPanelRef.current && !settingsPanelRef.current.contains(event.target as Node) &&
        settingsButtonRef.current && !settingsButtonRef.current.contains(event.target as Node)
      ) {
        setIsSelectorPanelOpen(false);
      }
    };
    if (isSelectorPanelOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isSelectorPanelOpen]);

  const handleAyahMemorizationClick = useCallback((ayah: Ayah | null) => {
    if (!ayah || isAyahPlaying) return;
    const currentCount = memorizationState[ayah.number] || 0;
    const nextCount = currentCount + 1;
    setMemorizationState(prevState => ({ ...prevState, [ayah.number]: nextCount }));
    if (nextCount <= 7) {
      playAyah(ayah);
    }
  }, [isAyahPlaying, memorizationState, playAyah]);

  const handleActionButtonClick = useCallback(() => {
    if (!selectedAyah || isAyahPlaying) return;
    const currentCount = memorizationState[selectedAyah.number] || 0;
    if (currentCount >= 7) {
      playAyah(selectedAyah);
    } else {
      handleAyahMemorizationClick(selectedAyah);
    }
  }, [selectedAyah, isAyahPlaying, memorizationState, playAyah, handleAyahMemorizationClick]);

  const handleSelfReadClick = useCallback(() => {
    if (!selectedAyah) return;
    setMemorizationState(prevState => ({
      ...prevState,
      [selectedAyah.number]: (prevState[selectedAyah.number] || 0) + 1,
    }));
  }, [selectedAyah]);

  const handleAyahNavigation = useCallback((direction: 'next' | 'prev') => {
    if (isAyahPlaying || !surahData || !selectedAyah) return;
    const currentIndex = surahData.ayahs.findIndex(a => a.number === selectedAyah.number);
    const nextIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;
    if (nextIndex >= 0 && nextIndex < surahData.ayahs.length) {
      setSelectedAyah(surahData.ayahs[nextIndex]);
    }
  }, [isAyahPlaying, surahData, selectedAyah]);

  const handleShowTafsir = (ayah: Ayah) => showTafsir(ayah, selectedTranslation);

  const handleAyahClick = (ayah: Ayah) => {
    if (selectedAyah?.number === ayah.number) {
        setSelectedAyah(null);
    } else {
        setSelectedAyah(ayah);
    }
  };

  const handleClosePlayer = useCallback(() => {
    setSelectedAyah(null);
  }, []);

  const isFirstAyah = selectedAyah?.number === surahData?.ayahs[0]?.number;
  const isLastAyahInQuran = selectedAyah?.number === surahData?.ayahs[surahData.ayahs.length - 1]?.number && selectedSurah === 114;

  const isLastSurah = selectedSurah === 114;
  const nextSurahInfo = !isLastSurah ? surahs.find(s => s.number === selectedSurah + 1) : null;
  const nextSurahName = nextSurahInfo ? nextSurahInfo.name : null;

  const handleGoToNextSurah = useCallback(() => {
      if (!isLastSurah) {
          const nextSurahNumber = selectedSurah + 1;
          setSelectedSurah(nextSurahNumber);
          setSelectedAyah(null); // Reset selected ayah
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  }, [isLastSurah, selectedSurah]);

  const surahInfoString = useMemo(() => {
    if (!surahData || !surahData.ayahs || surahData.ayahs.length === 0) {
      return surahData ? surahData.name : null;
    }

    const firstAyah = surahData.ayahs[0];
    const lastAyah = surahData.ayahs[surahData.ayahs.length - 1];

    const startJuz = firstAyah.juz;
    const endJuz = lastAyah.juz;
    const juzString = startJuz === endJuz ? `${t.juz} ${startJuz}` : `${t.juz} ${startJuz} - ${endJuz}`;

    const ayahsCount = surahData.ayahs.length;
    const ayahsString = `${ayahsCount} ${t.ayahs}`;

    return `${surahData.name} | ${juzString} | ${ayahsString}`;
  }, [surahData, t]);

  return (
    <div className="text-white min-h-screen flex flex-col">
      <div className="sticky top-0 z-30">
        <header className="bg-slate-800/80 backdrop-blur-sm shadow-lg border-b border-slate-700/50">
          <div className="container mx-auto flex justify-between items-center px-2 sm:px-4 md:px-6 py-2">
            <div>
              <h1 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl font-bold text-amber-400 leading-tight">{t.appTitle}</h1>
              <p className="text-sm sm:text-base text-gray-200 mt-1 leading-tight">{t.appSubtitle}</p>
              {surahInfoString && <p className="text-[10px] sm:text-xs text-gray-400 mt-1 truncate">{surahInfoString}</p>}
            </div>
            <div className="flex items-center gap-0">
               <HeaderButton
                  onClick={() => setLanguage(l => l === 'ar' ? 'en' : 'ar')}
                  label={language === 'ar' ? 'English' : 'عربي'}
                  title="Switch Language"
                  className="hover:bg-slate-700 text-white font-bold"
               >
                  {language === 'ar' ? 'EN' : 'ع'}
               </HeaderButton>
               <HeaderButton
                  onClick={() => setIsSelectorPanelOpen(p => !p)}
                  label={t.settings}
                  title={t.settings}
                  className="hover:bg-slate-700"
                  ref={settingsButtonRef}
               >
                 <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 transition-transform duration-300 ${isSelectorPanelOpen ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066 2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.096 2.572-1.065z" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                 </svg>
               </HeaderButton>
               <HeaderButton
                  onClick={() => setIsPrayerTimesOpen(true)}
                  label={t.prayerTimes}
                  title={t.prayerTimesTitle}
                  className="hover:bg-slate-700 text-white"
               >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                     <path strokeLinecap="round" strokeLinejoin="round" d="M3 21h18M5 21V9.586a1 1 0 01.293-.707l6-6a1 1 0 011.414 0l6 6a1 1 0 01.293.707V21M7 21v-4a1 1 0 011-1h8a1 1 0 011 1v4" />
                  </svg>
               </HeaderButton>
               <HeaderButton
                 onClick={() => toggleRadio(RADIO_STREAM_URL)}
                 label={t.radio}
                 title={t.radioTitle}
                 className={`hover:bg-slate-700 ${isRadioPlaying ? 'text-amber-400' : 'text-white'}`}
               >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                     <path strokeLinecap="round" strokeLinejoin="round" d="M18.364 5.636a9 9 0 010 12.728m-12.728-12.728a9 9 0 0112.728 0M12 18a6 6 0 100-12 6 6 0 000 12z" />
                     <path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
               </HeaderButton>
            </div>
          </div>
        </header>

        <div ref={settingsPanelRef} className={`absolute w-full z-20 transition-all duration-500 ease-in-out overflow-hidden ${isSelectorPanelOpen ? 'max-h-[30rem]' : 'max-h-0 opacity-0'}`}>
            <div className="p-4 md:p-6 bg-slate-900/90 backdrop-blur-sm shadow-lg">
              <div className="container mx-auto">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <SurahSelector surahs={surahs} selectedSurah={selectedSurah} onChange={(e) => setSelectedSurah(Number(e.target.value))} disabled={isLoading} />
                  <ReciterSelector reciters={RECITERS} selectedReciter={selectedReciter} onChange={(e) => setSelectedReciter(e.target.value)} disabled={isLoading} />
                  <TranslationSelector translations={TRANSLATIONS} selectedTranslation={selectedTranslation} onChange={(e) => setSelectedTranslation(e.target.value)} disabled={isLoading}/>
                </div>
              </div>

              <div 
                onClick={() => setIsSelectorPanelOpen(false)}
                className="mt-4 flex flex-col items-center justify-center text-gray-500 cursor-pointer hover:text-amber-400 transition-colors"
                role="button"
                aria-label={t.closeSettings}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M5 15l7-7 7 7" />
                  </svg>
                  <span className="text-xs font-semibold">{t.closeSettings}</span>
              </div>
               <div className="mt-6 text-center text-sm">
                  <p className="font-semibold text-lg" style={{ color: '#FFD700' }}>
                      {t.developedBy}
                  </p>
                  <p className="font-semibold text-lg" style={{ color: '#FFD700' }}>
                      {t.charity}
                  </p>
              </div>
            </div>
        </div>
      </div>

      <main className="container mx-auto px-2 py-4 sm:p-4 md:p-6 flex-grow">
        <ErrorMessage message={error} />
        <AyahDisplay
          surah={surahData}
          isLoading={isLoading}
          onAyahClick={handleAyahClick}
          memorizationState={memorizationState}
          selectedAyah={selectedAyah}
          ayahRefs={ayahRefs}
          onShowTafsir={handleShowTafsir}
          onGoToNextSurah={handleGoToNextSurah}
          nextSurahName={nextSurahName}
          isLastSurah={isLastSurah}
          t={t}
        />
      </main>

      <footer className="bg-slate-900/90 border-t border-slate-700/50 py-4 px-6 text-center text-sm">
        <div className="container mx-auto">
          <p className="font-semibold text-lg" style={{ color: '#FFD700' }}>
            {t.developedBy}
          </p>
          <p className="font-semibold text-lg" style={{ color: '#FFD700' }}>
            {t.charity}
          </p>
        </div>
      </footer>

      <PlayerControls
        ayah={selectedAyah}
        count={selectedAyah ? memorizationState[selectedAyah.number] || 0 : 0}
        isAudioPlaying={isAyahPlaying}
        onActionButtonClick={handleActionButtonClick}
        onSelfReadClick={handleSelfReadClick}
        onNext={() => handleAyahNavigation('next')}
        onPrevious={() => handleAyahNavigation('prev')}
        isLastAyah={isLastAyahInQuran}
        isFirstAyah={isFirstAyah}
        isVisible={!!selectedAyah}
        onClose={handleClosePlayer}
        t={t}
      />

      <TafsirModal
        isOpen={isTafsirOpen}
        onClose={closeTafsir}
        ayah={tafsirAyah}
        tafsirContent={tafsirContent}
        isLoading={isTafsirLoading}
        surahName={surahData?.name || ''}
        t={t}
      />

      <PrayerTimes
        isOpen={isPrayerTimesOpen}
        onClose={() => setIsPrayerTimesOpen(false)}
        data={prayerTimes}
        isLoading={isPrayerTimesLoading}
        error={prayerTimesError}
        currentLocation={location}
        onLocationChange={setLocation}
        t={t}
      />
    </div>
  );
}

import { useMemo } from 'react';

export const useActionButtonState = (count: number, t: any) => {
  return useMemo(() => {
    const isSelfReadingPhase = count >= 7;

    let actionButtonLabel = t.start;
    let ariaLabel = t.startMemorizing;
    let actionButtonColor = 'bg-teal-600 hover:bg-teal-700';

    if (isSelfReadingPhase) {
      actionButtonLabel = t.reListen;
      ariaLabel = t.reListenAyah;
      actionButtonColor = 'bg-sky-600 hover:bg-sky-700';
    } else if (count > 0) {
      actionButtonLabel = t.again;
      ariaLabel = t.listenAgain;
    }

    return { actionButtonLabel, ariaLabel, actionButtonColor, isSelfReadingPhase };
  }, [count, t]);
};

import React from 'react';
import { SurahData, Ayah } from '../types';
import { MEMORIZATION_COLORS } from '../constants';

interface AyahDisplayProps {
  surah: SurahData | null;
  isLoading: boolean;
  onAyahClick: (ayah: Ayah) => void;
  memorizationState: Record<number, number>;
  selectedAyah: Ayah | null;
  ayahRefs: React.MutableRefObject<Record<number, HTMLLIElement | null>>;
  onShowTafsir: (ayah: Ayah) => void;
  onGoToNextSurah: () => void;
  nextSurahName: string | null;
  isLastSurah: boolean;
  t: any;
}

const AyahSkeletonLoader: React.FC = () => (
    <div className="space-y-4 animate-pulse max-w-5xl mx-auto">
        {[...Array(5)].map((_, i) => (
            <div key={i} className="bg-slate-800/80 rounded-lg h-32 w-full">
                <div className="p-6">
                    <div className="h-6 bg-slate-700/80 rounded w-11/12 mb-4"></div>
                    <div className="h-6 bg-slate-700/80 rounded w-10/12"></div>
                </div>
            </div>
        ))}
    </div>
);


const AyahDisplay: React.FC<AyahDisplayProps> = ({ surah, isLoading, onAyahClick, memorizationState, selectedAyah, ayahRefs, onShowTafsir, onGoToNextSurah, nextSurahName, isLastSurah, t }) => {
  if (isLoading) {
    return <div className="text-center px-4"><AyahSkeletonLoader/></div>;
  }

  if (!surah) {
    return <div className="text-center p-10 text-xl text-white">{t.selectSurah}</div>;
  }

  let lastJuz = 0;
  let lastPage = 0;

  return (
    <div className="text-center px-4"> {/* Removed padding-bottom */}
      <h2 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl font-bold mb-2 text-amber-400 animate-fadeInUp opacity-0" style={{animationDelay: '100ms'}}>
        {surah.name} ({surah.englishName})
      </h2>
      <p className="mb-6 text-base sm:text-lg text-gray-400 animate-fadeInUp opacity-0" style={{animationDelay: '200ms'}}>{surah.revelationType === 'Meccan' ? t.meccan : t.medinan}</p>

      {surah.displayBasmalah && (
          <div className="my-8 animate-fadeInUp opacity-0" style={{animationDelay: '300ms'}}>
            <p className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-quran text-white">
              بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
            </p>
          </div>
      )}

      <ul className="space-y-4 max-w-5xl mx-auto">
        {surah.ayahs.map((ayah, index) => {
          const isSelected = selectedAyah?.number === ayah.number;
          const count = memorizationState[ayah.number] || 0;

          let colorClass = '';
          if (isSelected) {
            colorClass = 'bg-slate-700/50 scale-105 ring-2 ring-amber-400';
          } else {
            const displayCount = Math.min(count, 7);
            colorClass = MEMORIZATION_COLORS[displayCount] || MEMORIZATION_COLORS[0];
          }

          const juzChanged = ayah.juz !== lastJuz;
          const pageChanged = ayah.page !== lastPage;

          lastJuz = ayah.juz;
          lastPage = ayah.page;

          const animationDelay = Math.min(index * 20, 600); // Faster stagger, max 0.6s delay

          return (
            <React.Fragment key={ayah.number}>
              {juzChanged && (
                <div className="text-center my-6 pt-4 animate-fadeInUp opacity-0" style={{animationDelay: `${animationDelay}ms`}}>
                   <h3 className="inline-block px-4 py-2 text-2xl lg:text-3xl font-bold text-amber-400 bg-slate-700/70 rounded-lg shadow">
                        {t.juz} {ayah.juz}
                   </h3>
                </div>
              )}
               {pageChanged && (
                <div className="text-center my-4 text-gray-400 font-semibold flex items-center justify-center animate-fadeInUp opacity-0" style={{animationDelay: `${animationDelay}ms`}}>
                    <hr className="w-1/4 border-gray-600"/>
                    <span className="mx-4">{t.page} {ayah.page}</span>
                    <hr className="w-1/4 border-gray-600"/>
                </div>
              )}
              <li
                ref={(el) => (ayahRefs.current[ayah.number] = el)}
                onClick={() => onAyahClick(ayah)}
                className={`p-4 sm:p-6 rounded-lg shadow-md transition-all duration-300 cursor-pointer relative animate-fadeInUp opacity-0 ${colorClass}`}
                style={{animationDelay: `${animationDelay}ms`}}
                aria-selected={isSelected}
              >
                {count > 0 && (
                  <span className={`absolute top-2 right-2 text-white text-xs font-bold rounded-full h-6 w-6 flex items-center justify-center transition-colors ${count > 7 ? 'bg-amber-600' : 'bg-teal-600'}`}>
                    {count}
                  </span>
                )}

                <p className={`text-right text-2xl sm:text-3xl md:text-4xl lg:text-5xl leading-loose md:leading-relaxed font-quran ${isSelected ? 'text-white' : 'text-gray-200'}`} dir="rtl">
                  {ayah.text} <span className="text-amber-400">({ayah.numberInSurah})</span>
                </p>

                {ayah.translationText && (
                    <p className={`text-left text-base sm:text-lg lg:text-xl mt-4 text-gray-400`} dir="ltr">
                        {ayah.translationText}
                    </p>
                )}

                <div className="mt-6 pt-4 border-t border-slate-700 flex justify-start">
                  <button 
                    onClick={(e) => {
                        e.stopPropagation();
                        onShowTafsir(ayah);
                    }}
                    className="flex items-center gap-2 px-3 py-1.5 text-sm font-semibold text-amber-300 bg-slate-700/60 rounded-full hover:bg-slate-700 transition-all duration-200 active:scale-95"
                    aria-label={`${t.interpretation} ${ayah.numberInSurah}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                    </svg>
                    <span>{t.interpretation}</span>
                  </button>
                </div>
              </li>
            </React.Fragment>
          );
        })}
      </ul>

      {!isLastSurah && nextSurahName && (
        <div className="mt-12 text-center animate-fadeInUp opacity-0" style={{animationDelay: '800ms'}}>
            <button
                onClick={onGoToNextSurah}
                className="px-8 py-4 bg-amber-500 text-slate-900 font-bold text-lg rounded-lg shadow-lg hover:bg-amber-600 transition-all duration-300 transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 focus:ring-amber-400"
            >
                {t.goToSurah} {nextSurahName} {(document.dir === 'rtl') ? '←' : '→'}
            </button>
        </div>
      )}
    </div>
  );
};

export default React.memo(AyahDisplay);

import React from 'react';
import { Ayah } from '../types';
import AyahCounter from './AyahCounter';
import { useActionButtonState } from '../hooks/useActionButtonState';

interface PlayerControlsProps {
  ayah: Ayah | null;
  count: number;
  isAudioPlaying: boolean;
  onActionButtonClick: () => void;
  onSelfReadClick: () => void;
  onNext: () => void;
  onPrevious: () => void;
  isLastAyah: boolean;
  isFirstAyah: boolean;
  isVisible: boolean;
  onClose: () => void;
  t: any;
}

const PlayerControls: React.FC<PlayerControlsProps> = ({
  ayah,
  count,
  isAudioPlaying,
  onActionButtonClick,
  onSelfReadClick,
  onNext,
  onPrevious,
  isLastAyah,
  isFirstAyah,
  isVisible,
  onClose,
  t
}) => {
  const { actionButtonLabel, ariaLabel, actionButtonColor, isSelfReadingPhase } = useActionButtonState(count, t);

  const isMemorizationStarted = count > 0;

  return (
    <div className={`fixed bottom-0 left-0 right-0 bg-slate-800/90 backdrop-blur-sm border-t border-slate-700 z-20 shadow-lg transition-transform duration-500 ease-out ${isVisible ? 'translate-y-0' : 'translate-y-full'}`}>
      <div className="container mx-auto flex items-center justify-between gap-4 p-4">
        {!isMemorizationStarted ? (
          // "Start Banner" View when count is 0
          <>
            <div className="flex-1 min-w-0">
              <p className="text-gray-300 text-lg truncate" dir="rtl">
                {ayah?.text}
              </p>
            </div>
            <div className="flex items-center gap-x-4">
              <button
                onClick={onActionButtonClick}
                className="px-6 py-3 text-white font-semibold rounded-lg shadow-md transition-all duration-200 text-md active:scale-95 bg-teal-600 hover:bg-teal-700"
                aria-label={t.startMemorizingAyah}
              >
                {t.startMemorizing}
              </button>
              <button
                onClick={onClose}
                className="p-2 text-gray-400 hover:text-white transition-colors"
                aria-label={t.close}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          </>
        ) : (
          // Regular Player Controls View when count > 0
          <>
            <div className="flex items-center gap-4 flex-1 min-w-0">
              {ayah && <AyahCounter
                count={count}
                isAudioPlaying={isAudioPlaying}
                isSelfReadingPhase={isSelfReadingPhase}
