  isAudioPlaying: boolean;
  onActionButtonClick: () => void;
  onNext: () => void;
  isLastAyah: boolean;
  t: any;
}

const MemorizationView: React.FC<MemorizationViewProps> = ({ ayah, count, onClose, onMemorizeClick, isAudioPlaying, onActionButtonClick, onNext, isLastAyah, t }) => {
  const { actionButtonLabel, ariaLabel, actionButtonColor, isSelfReadingPhase } = useActionButtonState(count, t);

  let colorClass: string;
  if (count <= 7) {
    colorClass = MEMORIZATION_COLORS[count] || MEMORIZATION_COLORS[0];
  } else {
    const colorIndex = (count - 8) % SELF_READING_COLORS.length;
    colorClass = SELF_READING_COLORS[colorIndex];
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-80 flex items-center justify-center z-50 p-4">
      <div 
        className={`relative w-full max-w-6xl h-[85vh] p-8 md:p-12 rounded-2xl shadow-2xl transition-colors duration-300 flex flex-col justify-between items-center ${colorClass} bg-slate-800 ${isAudioPlaying ? 'cursor-wait' : 'cursor-pointer'}`}
        onClick={() => onMemorizeClick(ayah)}
      >
        <button 
          onClick={(e) => {
            e.stopPropagation();
            onClose();
          }}
          className="absolute top-4 right-4 bg-red-500 text-white rounded-full w-10 h-10 flex items-center justify-center text-2xl font-bold hover:bg-red-600 transition-colors z-10 disabled:opacity-50 disabled:cursor-not-allowed"
          aria-label={t.close}
          disabled={isAudioPlaying}
        >
          &times;
        </button>

        <div className="absolute top-4 left-4 text-sm text-gray-300 font-semibold bg-white/10 px-4 py-2 rounded-full">
            <span>{t.juz} {ayah.juz}</span>
            <span className="mx-2">|</span>
            <span>{t.page} {ayah.page}</span>
        </div>

        <div className="flex-grow w-full flex flex-col items-center justify-center overflow-y-auto px-4">
            <p className="text-4xl md:text-5xl lg:text-7xl font-quran text-gray-100 text-center leading-[2.2] md:leading-[2.4] lg:leading-[2.5]" dir="rtl">
                {ayah.text} <span className="text-amber-400 px-3">({ayah.numberInSurah})</span>
            </p>
            {ayah.translationText && (
                <p className="text-xl md:text-2xl mt-8 text-gray-300 text-center max-w-4xl leading-relaxed" dir="ltr">
                    {ayah.translationText}
                </p>
            )}
        </div>

        <div className="w-full flex flex-col items-center gap-y-6 pt-6 border-t border-white/5">
            <div className="flex flex-col items-center space-y-2">
                <AyahCounter
                    count={count}
                    isAudioPlaying={isAudioPlaying}
                    isSelfReadingPhase={isSelfReadingPhase}
                    size="large"
                />
            </div>
            <div className="flex justify-center items-center gap-x-6">
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        onActionButtonClick();
                    }}
                    disabled={isAudioPlaying}
                    className={`px-8 py-3.5 text-white font-bold rounded-xl shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed text-xl active:scale-95 ${actionButtonColor}`}
                    aria-label={ariaLabel}
                >
                    {actionButtonLabel}
                </button>
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        onNext();
                    }}
                    disabled={isAudioPlaying || isLastAyah}
                    className="px-6 py-3.5 bg-slate-700 text-white font-bold rounded-xl shadow-lg hover:bg-slate-600 transition-all disabled:opacity-50 disabled:cursor-not-allowed text-xl"
                    aria-label={t.nextAyah}
                >
                    {t.nextAyah}
                </button>
            </div>
             {isSelfReadingPhase && (
                <p className="text-center text-sm text-gray-400 mt-2 max-w-lg">
                    {t.selfReadingNote}
                </p>
            )}
        </div>
      </div>
    </div>
  );
};

export default MemorizationView;

import React, { useState, useEffect } from 'react';
import { Ayah, Tafsir } from '../types';

interface TafsirModalProps {
  isOpen: boolean;
  onClose: () => void;
  ayah: Ayah | null;
  tafsirContent: Tafsir | null;
  isLoading: boolean;
  surahName: string;
  t: any;
}

const RTL_LANGS = ['ar', 'ur', 'he', 'fa'];

const TafsirModal: React.FC<TafsirModalProps> = ({ isOpen, onClose, ayah, tafsirContent, isLoading, surahName, t }) => {
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setShowModal(true);
    } else {
      const timer = setTimeout(() => setShowModal(false), 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  if (!showModal) {
    return null;
  }

  const isRtl = (lang: string | undefined) => lang ? RTL_LANGS.includes(lang) : false;

  return (
    <div 
      className={`fixed inset-0 bg-black flex items-center justify-center z-50 p-4 transition-opacity duration-300 ${isOpen ? 'bg-opacity-80' : 'bg-opacity-0'}`}
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="tafsir-title"
    >
      <div 
        className={`bg-slate-800 w-full max-w-4xl max-h-[90vh] rounded-2xl shadow-2xl flex flex-col transition-all duration-300 ease-out ${isOpen ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 -translate-y-4 scale-95'}`}
        onClick={(e) => e.stopPropagation()}
      >
        <header className="p-6 border-b border-slate-700 flex justify-between items-center flex-shrink-0">
          <h2 id="tafsir-title" className="text-xl sm:text-2xl font-bold text-amber-400">
            {t.tafsirTitle} {ayah?.numberInSurah} {t.surah === 'سورة' ? 'من' : 'from'} {t.surah} {surahName}
          </h2>
          <button 
            onClick={onClose}
            className="bg-red-500 text-white rounded-full w-8 h-8 flex items-center justify-center text-xl font-bold hover:bg-red-600 transition-colors"
            aria-label={t.close}
          >
            &times;
          </button>
        </header>

        <div className="p-6 sm:p-10 border-b border-slate-700/50 flex-shrink-0 bg-slate-900/30">
          <p className="text-3xl md:text-4xl lg:text-5xl font-quran text-gray-100 text-right leading-[2.2] md:leading-[2.4]" dir="rtl">
            {ayah?.text}
          </p>
        </div>

        <div className="p-6 sm:p-10 overflow-y-auto flex-grow space-y-8">
          {isLoading ? (
            <div className="flex justify-center items-center h-40">
               <svg className="animate-spin h-12 w-12 text-amber-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
               </svg>
            </div>
          ) : tafsirContent ? (
            <>
              {tafsirContent.arabic && (
                <div>
                  <h3 className="text-xl font-bold text-amber-300 mb-4 text-right border-r-4 border-amber-500 pr-4">{t.tafsirMoyassar}</h3>
                  <p className="text-xl lg:text-2xl leading-[2.0] text-gray-300 text-right font-amiri whitespace-pre-wrap" dir="rtl">
                    {tafsirContent.arabic}
                  </p>
                </div>
              )}
              {tafsirContent.translation?.text && (
                <div className="pt-6 border-t border-slate-700/30">
                  <h3 
                    className={`text-xl font-bold text-amber-300 mb-4 border-l-4 border-amber-500 pl-4 ${isRtl(tafsirContent.translation.lang) ? 'text-right' : 'text-left'}`} 
                    dir={isRtl(tafsirContent.translation.lang) ? 'rtl' : 'ltr'}>
                    {tafsirContent.translation.name}
                  </h3>
                  <p 
                    className={`text-lg lg:text-xl leading-relaxed text-gray-300 whitespace-pre-wrap ${isRtl(tafsirContent.translation.lang) ? 'text-right' : 'text-left'}`} 
                    dir={isRtl(tafsirContent.translation.lang) ? 'rtl' : 'ltr'}>
                    {tafsirContent.translation.text}
                  </p>
                </div>
              )}
              {!tafsirContent.arabic && !tafsirContent.translation?.text && (
                 <p className="text-xl text-center text-red-400">
                    {t.tafsirErrorDetails}
                 </p>
              )}
            </>
          ) : (
            <p className="text-xl text-center text-red-400">
              {t.tafsirErrorDetails}
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default TafsirModal;

import { useState, useRef, useCallback, useEffect } from 'react';
import { Ayah } from '../types';

export const useAudioController = (onPlaybackEnd?: () => void) => {
    const [isAyahPlaying, setIsAyahPlaying] = useState(false);
    const [isRadioPlaying, setIsRadioPlaying] = useState(false);

    // Audio objects are kept in refs to persist across renders and prevent garbage collection issues
    const ayahAudioRef = useRef<HTMLAudioElement>(new Audio());
    const radioAudioRef = useRef<HTMLAudioElement>(new Audio());

    // Internal state to track if the radio SHOULD be playing, aiding recovery after network drops
    const shouldRadioBePlaying = useRef(false);

    // Helper to attempt radio playback with basic error catching
    const startRadio = useCallback(() => {
        const radio = radioAudioRef.current;
        if (radio.src && shouldRadioBePlaying.current) {
            radio.play().catch(error => {
                if (error.name !== 'AbortError') {
                    console.error("Radio playback recovery failed:", error);
                }
            });
        }
    }, []);

    // Effect for Ayah Audio Lifecycle
    useEffect(() => {
        const ayahAudio = ayahAudioRef.current;

        const onAyahEnded = () => {
            setIsAyahPlaying(false);
            onPlaybackEnd?.();
        };
        const onAyahPaused = () => setIsAyahPlaying(false);
        const onAyahPlay = () => setIsAyahPlaying(true);

        ayahAudio.addEventListener('ended', onAyahEnded);
        ayahAudio.addEventListener('pause', onAyahPaused);
        ayahAudio.addEventListener('play', onAyahPlay);

        return () => {
            ayahAudio.removeEventListener('ended', onAyahEnded);
            ayahAudio.removeEventListener('pause', onAyahPaused);
            ayahAudio.removeEventListener('play', onAyahPlay);
        };
    }, [onPlaybackEnd]);

    // Effect for Radio Audio Lifecycle & Media Session
    useEffect(() => {
        const radioAudio = radioAudioRef.current;
        const ayahAudio = ayahAudioRef.current;

        const onRadioPaused = () => {
            // Only update state to false if we explicitly stopped it
            if (!shouldRadioBePlaying.current) {
                setIsRadioPlaying(false);
            }
            if ('mediaSession' in navigator) {
                navigator.mediaSession.playbackState = 'paused';
            }
        };

        const onRadioPlay = () => {
            setIsRadioPlaying(true);
            shouldRadioBePlaying.current = true;
            if ('mediaSession' in navigator) {
                navigator.mediaSession.playbackState = 'playing';
            }
        };

        // Recovery triggers: When the stream stalls, waits for data, or errors out
        const recoverRadio = () => {
            if (shouldRadioBePlaying.current) {
                console.log("Radio stream interrupted. Attempting to resume...");
                startRadio();
            }
        };

        radioAudio.addEventListener('pause', onRadioPaused);
        radioAudio.addEventListener('play', onRadioPlay);
        radioAudio.addEventListener('stalled', recoverRadio);
        radioAudio.addEventListener('waiting', recoverRadio);
        radioAudio.addEventListener('error', recoverRadio);

        // Media Session setup for background persistence and lock-screen controls
        if ('mediaSession' in navigator) {
            navigator.mediaSession.setActionHandler('play', () => {
                if (shouldRadioBePlaying.current) {
                    ayahAudio.pause();
                    startRadio();
                }
            });
            navigator.mediaSession.setActionHandler('pause', () => {
                radioAudio.pause();
                shouldRadioBePlaying.current = false;
                setIsRadioPlaying(false);
            });
            navigator.mediaSession.setActionHandler('stop', () => {
                radioAudio.pause();
                radioAudio.src = ""; // Clear source to stop buffering
                shouldRadioBePlaying.current = false;
                setIsRadioPlaying(false);
            });
        }

        return () => {
            radioAudio.removeEventListener('pause', onRadioPaused);
            radioAudio.removeEventListener('play', onRadioPlay);
            radioAudio.removeEventListener('stalled', recoverRadio);
            radioAudio.removeEventListener('waiting', recoverRadio);
            radioAudio.removeEventListener('error', recoverRadio);
            if ('mediaSession' in navigator) {
                navigator.mediaSession.setActionHandler('play', null);
                navigator.mediaSession.setActionHandler('pause', null);
                navigator.mediaSession.setActionHandler('stop', null);
            }
        };
    }, [startRadio]);

    const playAyah = useCallback((ayah: Ayah) => {
        if (ayah.audio) {
            // Pause radio temporarily when an Ayah is played
            radioAudioRef.current.pause();

            const audioSrc = ayah.audio.replace('http:', 'https:');
            if (ayahAudioRef.current.src !== audioSrc) {
                ayahAudioRef.current.src = audioSrc;
            }
            ayahAudioRef.current.currentTime = 0;
            const playPromise = ayahAudioRef.current.play();
            if (playPromise !== undefined) {
                playPromise.catch(error => {
                    if (error.name !== 'AbortError') {
                        console.error("Ayah playback failed", error);
                    }
                });
            }
        }
    }, []);

    const toggleRadio = useCallback((streamUrl: string) => {
        const radioAudio = radioAudioRef.current;
        if (isRadioPlaying) {
            shouldRadioBePlaying.current = false;
            radioAudio.pause();
            setIsRadioPlaying(false);
        } else {
            // Stop ayah if playing
            ayahAudioRef.current.pause();

            if (radioAudio.src !== streamUrl) {
                radioAudio.src = streamUrl;
                radioAudio.load(); // Force load to fresh buffer
            }

            if ('mediaSession' in navigator) {
                navigator.mediaSession.metadata = new MediaMetadata({
                    title: 'إذاعة القرآن الكريم',
                    artist: 'المعين لحفظ القرآن الكريم',
                    album: 'بث مباشر',
                    artwork: [
                      { src: '/favicon.svg', sizes: '512x512', type: 'image/svg+xml' }
                    ]
                });
            }

            shouldRadioBePlaying.current = true;
            startRadio();
        }
    }, [isRadioPlaying, startRadio]);

    return {
        isAyahPlaying,
        playAyah,
        isRadioPlaying,
        toggleRadio,
    };
};

import React from 'react';
import { SurahData, Ayah } from '../types';
import { MEMORIZATION_COLORS } from '../constants';

interface AyahDisplayProps {
  surah: SurahData | null;
  isLoading: boolean;
  onAyahClick: (ayah: Ayah) => void;
  memorizationState: Record<number, number>;
  selectedAyah: Ayah | null;
  ayahRefs: React.MutableRefObject<Record<number, HTMLLIElement | null>>;
  onShowTafsir: (ayah: Ayah) => void;
  onGoToNextSurah: () => void;
  nextSurahName: string | null;
  isLastSurah: boolean;
  t: any;
}

const AyahSkeletonLoader: React.FC = () => (
    <div className="space-y-4 animate-pulse max-w-5xl mx-auto">
        {[...Array(5)].map((_, i) => (
            <div key={i} className="bg-slate-800/80 rounded-lg h-32 w-full">
                <div className="p-6">
                    <div className="h-6 bg-slate-700/80 rounded w-11/12 mb-4"></div>
                    <div className="h-6 bg-slate-700/80 rounded w-10/12"></div>
                </div>
            </div>
        ))}
    </div>
);


const AyahDisplay: React.FC<AyahDisplayProps> = ({ surah, isLoading, onAyahClick, memorizationState, selectedAyah, ayahRefs, onShowTafsir, onGoToNextSurah, nextSurahName, isLastSurah, t }) => {
  if (isLoading) {
    return <div className="text-center px-4"><AyahSkeletonLoader/></div>;
  }

  if (!surah) {
    return <div className="text-center p-10 text-xl text-white">{t.selectSurah}</div>;
  }

  let lastJuz = 0;
  let lastPage = 0;

  return (
    <div className="text-center px-4">
      <h2 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl font-bold mb-2 text-amber-400 animate-fadeInUp opacity-0" style={{animationDelay: '100ms'}}>
        {surah.name} ({surah.englishName})
      </h2>
      <p className="mb-6 text-base sm:text-lg text-gray-400 animate-fadeInUp opacity-0" style={{animationDelay: '200ms'}}>{surah.revelationType === 'Meccan' ? t.meccan : t.medinan}</p>

      {surah.displayBasmalah && (
          <div className="my-8 animate-fadeInUp opacity-0" style={{animationDelay: '300ms'}}>
            <p className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-quran text-white leading-[2.1]">
              بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
            </p>
          </div>
      )}

      <ul className="space-y-6 max-w-5xl mx-auto">
        {surah.ayahs.map((ayah, index) => {
          const isSelected = selectedAyah?.number === ayah.number;
          const count = memorizationState[ayah.number] || 0;

          let colorClass = '';
          if (isSelected) {
            colorClass = 'bg-slate-700/50 scale-[1.01] ring-2 ring-amber-400';
          } else {
            const displayCount = Math.min(count, 7);
            colorClass = MEMORIZATION_COLORS[displayCount] || MEMORIZATION_COLORS[0];
          }

          const juzChanged = ayah.juz !== lastJuz;
          const pageChanged = ayah.page !== lastPage;

          lastJuz = ayah.juz;
          lastPage = ayah.page;

          const animationDelay = Math.min(index * 20, 600);

          return (
            <React.Fragment key={ayah.number}>
              {juzChanged && (
                <div className="text-center my-8 pt-4 animate-fadeInUp opacity-0" style={{animationDelay: `${animationDelay}ms`}}>
                   <h3 className="inline-block px-6 py-2 text-2xl lg:text-3xl font-bold text-amber-400 bg-slate-700/70 rounded-lg shadow-lg">
                        {t.juz} {ayah.juz}
                   </h3>
                </div>
              )}
               {pageChanged && (
                <div className="text-center my-5 text-gray-400 font-semibold flex items-center justify-center animate-fadeInUp opacity-0" style={{animationDelay: `${animationDelay}ms`}}>
                    <hr className="w-1/4 border-gray-600"/>
                    <span className="mx-4">{t.page} {ayah.page}</span>
                    <hr className="w-1/4 border-gray-600"/>
                </div>
              )}
              <li
                ref={(el) => (ayahRefs.current[ayah.number] = el)}
                onClick={() => onAyahClick(ayah)}
                className={`p-5 sm:p-7 md:p-8 rounded-xl shadow-md transition-all duration-300 cursor-pointer relative animate-fadeInUp opacity-0 ${colorClass}`}
                style={{animationDelay: `${animationDelay}ms`}}
                aria-selected={isSelected}
              >
                {count > 0 && (
                  <span className={`absolute top-2.5 right-2.5 text-white text-xs font-bold rounded-full h-7 w-7 flex items-center justify-center transition-colors shadow-sm ${count > 7 ? 'bg-amber-600' : 'bg-teal-600'}`}>
                    {count}
                  </span>
                )}

                <p className={`text-right text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-quran leading-[2.1] sm:leading-[2.2] md:leading-[2.3] lg:leading-[2.4] ${isSelected ? 'text-white' : 'text-gray-100'}`} dir="rtl">
                  {ayah.text} <span className="text-amber-400 inline-block px-1">({ayah.numberInSurah})</span>
                </p>

                {ayah.translationText && (
                    <p className={`text-left text-base sm:text-lg lg:text-xl mt-5 text-gray-400 leading-relaxed`} dir="ltr">
                        {ayah.translationText}
                    </p>
                )}

                <div className="mt-6 pt-4 border-t border-slate-700/50 flex justify-start">
                  <button 
                    onClick={(e) => {
                        e.stopPropagation();
                        onShowTafsir(ayah);
                    }}
                    className="flex items-center gap-2 px-4 py-1.5 text-sm font-semibold text-amber-300 bg-slate-700/60 rounded-full hover:bg-slate-700 transition-all duration-200"
                    aria-label={`${t.interpretation} ${ayah.numberInSurah}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                    </svg>
                    <span>{t.interpretation}</span>
                  </button>
                </div>
              </li>
            </React.Fragment>
          );
        })}
      </ul>

      {!isLastSurah && nextSurahName && (
        <div className="mt-12 mb-8 text-center animate-fadeInUp opacity-0" style={{animationDelay: '800ms'}}>
            <button
                onClick={onGoToNextSurah}
                className="px-8 py-4 bg-amber-500 text-slate-900 font-bold text-lg rounded-lg shadow-lg hover:bg-amber-600 transition-all duration-300 transform hover:scale-105"
            >
                {t.goToSurah} {nextSurahName} {(document.dir === 'rtl') ? '←' : '→'}
            </button>
        </div>
      )}
    </div>
  );
};

export default React.memo(AyahDisplay);
